INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('itoi-shigesato-no-bass-tsuri-no-1-kettei-ban!-japan', 'N64', 'Itoi Shigesato no Bass Tsuri No. 1 Kettei Ban! (Japan)', '1997', 'Sports', 'HAL Laboratory', '1', 'Fishing', 'Realistic bass fishing simulation with Shigesato Itoi''s input.', 'Catch the biggest bass and win the professional tournament.', 'The definitive Japan-exclusive fishing game for N64.', 'Itoi Shigesato no Bass Tsuri No. 1 features beautiful water physics and deep management. Experience the most authentic fishing simulation available on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-dynamite-soccer-64-japan', 'N64', 'J.League Dynamite Soccer 64 (Japan)', '1997', 'Sports', 'KONAMI', '4', 'Soccer', 'Fast-paced 3D soccer with licensed J.League teams.', 'Lead your Japanese club to the league championship.', 'A high-energy soccer title exclusive to the Japanese market.', 'J.League Dynamite Soccer 64 offers arcade-style football with smooth animations. Experience the passion of Japanese soccer with official teams and rosters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-eleven-beat-1997-japan', 'N64', 'J.League Eleven Beat 1997 (Japan)', '1997', 'Sports', 'KONAMI', '4', 'Soccer', 'Strategic 3D soccer simulation and management.', 'Master the timing of the "Eleven Beat" to score spectacular goals.', 'A unique rhythm-influenced soccer game for Japan.', 'J.League Eleven Beat 1997 focuses on the timing of passes and shots. It''s a creative take on the sport with official J.League licensing for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-live-64-japan', 'N64', 'J.League Live 64 (Japan)', '1997', 'Sports', 'KONAMI', '4', 'Soccer', 'Realistic soccer simulation with broadcast-style presentation.', 'Win the J.League cup in this Konami-developed title.', 'A polished Japanese soccer sim from the ISS era.', 'J.League Live 64 features realistic player models and commentary. Experience the atmosphere of a live Japanese soccer broadcast on your Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-tactics-soccer-japan', 'N64', 'J.League Tactics Soccer (Japan)', '1999', 'Strategy', 'KONAMI', '1', 'Soccer Strategy', 'Tactical soccer simulation with a focus on management.', 'Manage your team''s formation and strategy to win the league.', 'A deep, menu-driven soccer strategy game for Japan.', 'J.League Tactics Soccer emphasizes the managerial side of the sport. Plan your plays and guide your team to glory in this technical N64 exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jleague-tactics-soccer-japan-rev-a', 'N64', 'J.League Tactics Soccer (Japan) (Rev A)', '1999', 'Strategy', 'KONAMI', '1', 'Soccer Strategy', 'Tactical soccer simulation with technical refinements.', 'Conquer the league with the most stable strategy build.', 'An updated Japanese revision of J.League Tactics Soccer.', 'J.League Tactics Soccer (Rev A) provides minor balance tweaks and performance improvements, ensuring a smoother managerial experience on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jangou-simulation-mahjong-dou-64-japan', 'N64', 'Jangou Simulation Mahjong Dou 64 (Japan)', '1997', 'Tabletop', 'SETA', '4', 'Mahjong', 'Professional Mahjong simulation and management.', 'Defeat the masters of Mahjong in a realistic 3D tournament.', 'A specialized Japan-exclusive Mahjong simulation.', 'Jangou Simulation Mahjong Dou 64 features deep tactical gameplay and multiple game modes. Perfect for fans of the traditional tile-based strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jayden-the-hedgehog', 'N64', 'Jayden The Hedgehog', '2022', 'Platformer', 'Independent', '1', 'Fan Game', '3D platforming featuring a custom hedgehog character.', 'Explore the levels as the high-speed Jayden.', 'A character-focused mod for the Super Mario 64 engine.', 'Jayden The Hedgehog brings a custom fan-character to life in 3D. Experience the classic platforming with unique animations and a fresh look on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeopardy!-usa', 'N64', 'Jeopardy! (USA)', '1998', 'Trivia', 'GameTek', '3', 'Game Show', 'Trivia-based game show simulation.', 'Answer questions correctly to win the grand prize.', 'The official N64 version of the famous American game show.', 'Jeopardy! (USA) features over 4,000 questions and the likeness of Alex Trebek. Test your knowledge in this faithful digital recreation of the TV hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeremy-mcgrath-supercross-2000-europe', 'N64', 'Jeremy McGrath Supercross 2000 (Europe)', '1999', 'Sports', 'Acclaim', '2', 'Motocross Racing', 'High-speed motocross racing and freestyle stunts.', 'Win the Supercross championship as the legendary McGrath.', 'The European release of the dirt-bike racing title.', 'Jeremy McGrath Supercross 2000 features realistic physics and a deep career mode. Master the jumps and corners to become a motocross legend on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeremy-mcgrath-supercross-2000-usa', 'N64', 'Jeremy McGrath Supercross 2000 (USA)', '1999', 'Sports', 'Acclaim', '2', 'Motocross Racing', 'High-speed motocross racing and freestyle stunts.', 'Conquer the tracks and unlock secret bike parts.', 'The North American release of the Supercross hit.', 'Jeremy McGrath Supercross 2000 (USA) offers 28 tracks and a robust track editor. Experience the thrill of professional indoor and outdoor motocross.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jet-force-gemini-europe-enfrdees', 'N64', 'Jet Force Gemini (Europe) (En,Fr,De,Es)', '1999', 'Action Adventure', 'Rare', '1', 'Shooter Adventure', 'Third-person sci-fi shooter with exploration and Gore.', 'Save the Tribals and stop Mizar''s insectoid army.', 'The European multi-language release of Rare''s epic shooter.', 'Jet Force Gemini (Europe) features massive worlds and three unique playable characters. Experience intense combat and non-linear exploration on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jet-force-gemini-usa', 'N64', 'Jet Force Gemini (USA)', '1999', 'Action Adventure', 'Rare', '1', 'Shooter Adventure', 'Third-person sci-fi shooter with exploration and Gore.', 'Complete the ultimate quest to save the galaxy from Mizar.', 'The definitive North American release of the Rare classic.', 'Jet Force Gemini (USA) is a technical powerhouse with cinematic music and a wide variety of futuristic weapons. It’s one of the most ambitious titles on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jet-the-hawk-64-rainbow', 'N64', 'Jet The Hawk 64 Rainbow', '2020', 'Action', 'Independent', '1', 'Fan Game', '3D platforming featuring a colorful custom hawk model.', 'Fly and dash through levels as Jet the Hawk.', 'A character-swap mod featuring the Sonic Riders character.', 'Jet The Hawk 64 Rainbow brings the leader of the Babylon Rogues to the N64. Enjoy high-speed platforming with custom models and vibrant colors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-g1-stable-japan', 'N64', 'Jikkyou G1 Stable (Japan)', '1999', 'Sports', 'KONAMI', '1', 'Horse Racing', 'Horse racing management and simulation.', 'Breed, train, and race champions in the G1 circuit.', 'A realistic horse racing sim exclusive to Japan.', 'Jikkyou G1 Stable offers a deep look into the world of equestrian sports. Manage every detail of your stable to produce a legendary racer on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-g1-stable-japan-rev-a', 'N64', 'Jikkyou G1 Stable (Japan) (Rev A)', '1999', 'Sports', 'KONAMI', '1', 'Horse Racing', 'Horse racing management and simulation with fixes.', 'Win the Triple Crown with the most stable Japanese build.', 'An updated revision of the G1 Stable simulation.', 'Jikkyou G1 Stable (Rev A) provides technical refinements to the horse training and racing mechanics, ensuring smooth performance on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-jleague-1999---perfect-striker-2-japan', 'N64', 'Jikkyou J.League 1999 - Perfect Striker 2 (Japan)', '1999', 'Sports', 'KONAMI', '4', 'Soccer', 'Professional soccer with 1999 J.League rosters.', 'Win the league in the ultimate "Perfect Striker" edition.', 'The expanded Japanese sequel to the original ISS/Perfect Striker.', 'Perfect Striker 2 features the "Success Mode" where you train a single player. It''s the most feature-rich soccer game of its year for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-jleague-1999---perfect-striker-2-japan-rev-a', 'N64', 'Jikkyou J.League 1999 - Perfect Striker 2 (Japan) (Rev A)', '1999', 'Sports', 'KONAMI', '4', 'Soccer', 'Professional soccer with technical refinements.', 'Lead your team to victory with the most polished 1999 build.', 'An updated revision of Perfect Striker 2 for Japan.', 'Jikkyou J.League 1999 (Rev A) offers minor bug fixes and performance tweaks, making it the definitive way to play Konami''s ''99 soccer hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-jleague-perfect-striker-japan', 'N64', 'Jikkyou J.League Perfect Striker (Japan)', '1996', 'Sports', 'KONAMI', '4', 'Soccer', 'Professional soccer with arcade-style movement and J.League teams.', 'Become the champion of Japan in the first Perfect Striker.', 'The Japan-exclusive counterpart to International Superstar Soccer 64.', 'Jikkyou J.League Perfect Striker features all the official clubs and players. It set the standard for 3D soccer gameplay on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-2000-japan', 'N64', 'Jikkyou Powerful Pro Yakyuu 2000 (Japan)', '2000', 'Sports', 'KONAMI', '4', 'Baseball', 'Arcade-style baseball with deep RPG "Success Mode".', 'Lead your "cabezon" team to the Japan Series championship.', 'The 2000 edition of the popular baseball series in Japan.', 'Jikkyou Powerful Pro Yakyuu 2000 features updated rosters and improved graphics. Train your own player in the legendary Success Mode on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-2000-japan-rev-a', 'N64', 'Jikkyou Powerful Pro Yakyuu 2000 (Japan) (Rev A)', '2000', 'Sports', 'KONAMI', '4', 'Baseball', 'Arcade-style baseball with final technical corrections.', 'Win the pennant with the most stable 2000 version.', 'An updated Japanese revision of the 2000 baseball title.', 'Powerful Pro Yakyuu 2000 (Rev A) provides performance optimizations, ensuring the smoothest home run derbies and pitching on original hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-4-japan', 'N64', 'Jikkyou Powerful Pro Yakyuu 4 (Japan)', '1997', 'Sports', 'KONAMI', '4', 'Baseball', 'Arcade-style baseball with the 1997 roster.', 'Master the art of pitching and batting in this 4th entry.', 'The first Powerful Pro Yakyuu title for the N64 in Japan.', 'Jikkyou Powerful Pro Yakyuu 4 introduced the series'' signature style to the 64-bit era. Experience addictive gameplay and a deep training mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-4-japan-rev-a', 'N64', 'Jikkyou Powerful Pro Yakyuu 4 (Japan) (Rev A)', '1997', 'Sports', 'KONAMI', '4', 'Baseball', 'Arcade-style baseball with minor technical fixes.', 'Conquer the league with the improved 4th edition.', 'An updated revision of the 4th Powerful Pro Yakyuu title.', 'Powerful Pro Yakyuu 4 (Rev A) offers small stability fixes for the Japanese market, maintaining the high quality of Konami''s baseball sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-5-japan', 'N64', 'Jikkyou Powerful Pro Yakyuu 5 (Japan)', '1998', 'Sports', 'KONAMI', '4', 'Baseball', 'Arcade-style baseball with expanded "Success Mode".', 'Build the ultimate team in the 1998 season edition.', 'The 5th entry in the popular Japanese baseball series.', 'Jikkyou Powerful Pro Yakyuu 5 features a more complex player creation system. It’s a classic of the genre that combines fun visuals with deep strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-5-japan-rev-a', 'N64', 'Jikkyou Powerful Pro Yakyuu 5 (Japan) (Rev A)', '1998', 'Sports', 'KONAMI', '4', 'Baseball', 'Arcade-style baseball with initial bug fixes.', 'Master the diamond in this refined 5th installment.', 'The first update revision for Powerful Pro Yakyuu 5.', 'Powerful Pro Yakyuu 5 (Rev A) addresses minor logic and roster issues, providing a more balanced experience for N64 players in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-5-japan-rev-b', 'N64', 'Jikkyou Powerful Pro Yakyuu 5 (Japan) (Rev B)', '1998', 'Sports', 'KONAMI', '4', 'Baseball', 'Arcade-style baseball with final technical polish.', 'Experience the best of the 1998 season with this build.', 'The final technical revision of Powerful Pro Yakyuu 5.', 'Powerful Pro Yakyuu 5 (Rev B) is the most refined version of this entry, offering optimized performance and corrected event triggers for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-6-japan', 'N64', 'Jikkyou Powerful Pro Yakyuu 6 (Japan)', '1999', 'Sports', 'KONAMI', '4', 'Baseball', 'Arcade-style baseball with 1999 rosters and new modes.', 'Win the championship in the most advanced 64-bit entry.', 'The 6th installment of the Powerful Pro Yakyuu series.', 'Jikkyou Powerful Pro Yakyuu 6 is widely considered the peak of the series on N64. It features a massive Success Mode and fluid 60 FPS gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-6-japan-rev-a', 'N64', 'Jikkyou Powerful Pro Yakyuu 6 (Japan) (Rev A)', '1999', 'Sports', 'KONAMI', '4', 'Baseball', 'Arcade-style baseball with initial technical refinements.', 'Lead your custom player to glory in this updated 6th edition.', 'The first revision of the acclaimed 6th baseball title.', 'Powerful Pro Yakyuu 6 (Rev A) provides performance tweaks and minor bug fixes, ensuring the best possible gameplay for Japanese baseball fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-6-japan-rev-b', 'N64', 'Jikkyou Powerful Pro Yakyuu 6 (Japan) (Rev B)', '1999', 'Sports', 'KONAMI', '4', 'Baseball', 'Arcade-style baseball with final asset corrections.', 'Conquer the Japanese baseball world with the stable build.', 'The final technical revision of Powerful Pro Yakyuu 6.', 'Powerful Pro Yakyuu 6 (Rev B) is the definitive version of the game, fixing rare glitches and offering the ultimate Success Mode experience on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-basic-ban-2001-japan', 'N64', 'Jikkyou Powerful Pro Yakyuu Basic Ban 2001 (Japan)', '2001', 'Sports', 'KONAMI', '4', 'Baseball', 'Arcade-style baseball with updated 2001 rosters.', 'Win the pennant in the final N64 entry of the series.', 'A specialized "Basic" version of the baseball hit for Japan.', 'Jikkyou Powerful Pro Yakyuu Basic Ban 2001 offers the most up-to-date rosters for the N64 era. Experience the polished "Success Mode" and tight gameplay of Konami''s baseball swan song.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-basic-ban-2001-japan-rev-a', 'N64', 'Jikkyou Powerful Pro Yakyuu Basic Ban 2001 (Japan) (Rev A)', '2001', 'Sports', 'KONAMI', '4', 'Baseball', 'Arcade-style baseball with final technical fixes.', 'Master the diamond with the most stable 2001 build.', 'The final technical revision of the 2001 baseball title.', 'Powerful Pro Yakyuu Basic Ban 2001 (Rev A) provides minor performance tweaks and roster corrections, ensuring a smooth and authentic Japanese baseball experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-world-soccer---world-cup-france-98-japan', 'N64', 'Jikkyou World Soccer - World Cup France ''98 (Japan)', '1998', 'Sports', 'KONAMI', '4', 'Soccer', 'Professional soccer featuring the 1998 World Cup.', 'Lead your favorite national team to victory in France.', 'The Japanese release of the legendary World Cup 98.', 'Jikkyou World Soccer - World Cup France ''98 features the official tournament license. Experience 64-bit football with real teams, stadiums, and the iconic World Cup atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-world-soccer---world-cup-france-98-japan-rev-a', 'N64', 'Jikkyou World Soccer - World Cup France ''98 (Japan) (Rev A)', '1998', 'Sports', 'KONAMI', '4', 'Soccer', 'Professional soccer with initial logic polish.', 'Conquer the international circuit with improved stability.', 'The first updated revision of the World Cup 98 title.', 'Jikkyou World Soccer France ''98 (Rev A) addresses minor gameplay bugs, offering more balanced AI and smoother player transitions for N64 soccer fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-world-soccer---world-cup-france-98-japan-rev-b', 'N64', 'Jikkyou World Soccer - World Cup France ''98 (Japan) (Rev B)', '1998', 'Sports', 'KONAMI', '4', 'Soccer', 'Professional soccer with final technical corrections.', 'Win the final match with the most refined 1998 build.', 'The definitive technical revision of the World Cup 98 game.', 'Jikkyou World Soccer France ''98 (Rev B) is the most polished version of the tournament, featuring optimized performance and corrected event triggers on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-world-soccer-3-japan', 'N64', 'Jikkyou World Soccer 3 (Japan)', '2002', 'Sports', 'KONAMI', '4', 'Soccer', 'Professional soccer with 1997 club and national teams.', 'Master the field in this Japan-exclusive soccer sim.', 'The Japanese precursor to the international ISS series.', 'Jikkyou World Soccer 3 features the classic Konami soccer engine. Experience fluid 3D animations and deep tactical options in this polished Japanese 64-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikuu-senshi-turok-japan', 'N64', 'Jikuu Senshi Turok (Japan)', '1997', 'Action', 'Iguana Entertainment', '1', 'First-Person Shooter', 'First-person shooter with dinosaurs and sci-fi weapons.', 'Stop the Campaigner and recover the Chronoscepter.', 'The Japanese release of the original Turok: Dinosaur Hunter.', 'Jikuu Senshi Turok brings the intense fog-filled action to Japan. Hunt raptors and cyborgs in this landmark FPS that defined the N64''s early power.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jinsei-game-64-japan', 'N64', 'Jinsei Game 64 (Japan)', '1999', 'Board Game', 'Takara', '4', 'Life Simulation', 'Digital board game based on the famous "Game of Life".', 'Navigate through life, earn money, and retire rich.', 'A vibrant and fun Japan-exclusive digital board game.', 'Jinsei Game 64 is a 3D adaptation of the classic Hasbro game. Play with friends through multiple life paths and funny events in this colorful N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('john-romeros-daikatana-europe-enfrde', 'N64', 'John Romero''s Daikatana (Europe) (En,Fr,De)', '2000', 'Action', 'Ion Storm', '1', 'First-Person Shooter', 'First-person shooter with time-travel and sidekicks.', 'Defeat Mishima across four distinct historical time periods.', 'The European version of the high-profile John Romero FPS.', 'John Romero''s Daikatana (Europe) features a unique companion system and a wide variety of weapons. Travel from Ancient Greece to the future in this ambitious N64 port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('john-romeros-daikatana-japan', 'N64', 'John Romero''s Daikatana (Japan)', '2000', 'Action', 'Ion Storm', '1', 'First-Person Shooter', 'First-person shooter with localized Japanese text.', 'Master the legendary blade in this Japanese edition.', 'The Japanese release of the time-traveling shooter.', 'John Romero''s Daikatana (Japan) offers the full FPS experience with localized menus. Battle robotic and mythical foes as Hiro Miyamoto on your Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('john-romeros-daikatana-usa', 'N64', 'John Romero''s Daikatana (USA)', '2000', 'Action', 'Ion Storm', '1', 'First-Person Shooter', 'First-person shooter with time-travel and sidekicks.', 'Reclaim the Daikatana and restore the timeline.', 'The North American release of the controversial shooter.', 'John Romero''s Daikatana (USA) is an N64 exclusive version of the PC game. Featuring unique graphics and a focus on action, it''s a fascinating piece of 64-bit history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jump-man-lxiv', 'N64', 'Jump Man LXIV', '2021', 'Platformer', 'Independent', '1', 'Fan Game', 'High-difficulty 3D platforming with retro assets.', 'Navigate through complex levels as the classic Jump Man.', 'A precision-focused platforming mod for Mario 64.', 'Jump Man LXIV is a tribute to the roots of the genre. Master tight jumps and environmental hazards in this challenging and creative N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kakutou-denshou---f-cup-maniax-japan', 'N64', 'Kakutou Denshou - F-Cup Maniax (Japan)', '1998', 'Fighting', 'Konami', '2', 'Arcade Fighting', '3D weapon-based fighting game with customization.', 'Win the F-Cup tournament and master your martial arts.', 'A Japan-exclusive 3D brawler (International title: G.A.S.P!!).', 'Kakutou Denshou - F-Cup Maniax features a deep move-creation system. Train your fighter and climb the ranks in this stylized 64-bit fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ken-&-ryu-in-smash-remix-v141', 'N64', 'Ken & Ryu in Smash Remix v1.4.1', '2023', 'Fighting', 'Fan Project', '4', 'Fan Game', '2D crossover fighting game featuring Street Fighter icons.', 'Master the Hadouken and Shoryuken in the Smash arena.', 'A high-quality character mod for Smash Remix.', 'Ken & Ryu in Smash Remix v1.4.1 brings the Street Fighter legends to the N64. Use their classic move-sets to dominate the battlefield in this incredible fan expansion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ken-griffey-jrs-slugfest-usa', 'N64', 'Ken Griffey Jr.''s Slugfest (USA)', '1999', 'Sports', 'Angel Studios', '4', 'Baseball', 'Arcade-style baseball with realistic player likeness.', 'Lead Ken Griffey Jr. to the World Series championship.', 'A fan-favorite arcade baseball game for the N64.', 'Ken Griffey Jr.''s Slugfest (USA) features fast-paced gameplay and iconic home run calls. It’s one of the most accessible and fun sports games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killer-instinct-gold-europe', 'N64', 'Killer Instinct Gold (Europe)', '1996', 'Fighting', 'Rare', '2', 'Arcade Fighting', '2D/3D fighting game with intense combos and finishers.', 'Master the "No Mercy" moves and defeat Eyedol.', 'The European version of the arcade-perfect brawler.', 'Killer Instinct Gold (Europe) features a massive roster and deep combo systems. Experience the high-energy fighting action with optimized PAL performance on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killer-instinct-gold-usa', 'N64', 'Killer Instinct Gold (USA)', '1996', 'Fighting', 'Rare', '2', 'Arcade Fighting', '2D/3D fighting game with intense combos and finishers.', 'Reach the top of the tower and unlock secret characters.', 'The original North American release of Killer Instinct Gold.', 'Killer Instinct Gold (USA) is a staple of the fighting genre. With its unique "C-C-C-Combo Breaker" system and cinematic music, it''s an N64 masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killer-instinct-gold-usa-rev-a', 'N64', 'Killer Instinct Gold (USA) (Rev A)', '1996', 'Fighting', 'Rare', '2', 'Arcade Fighting', '2D/3D fighting game with initial bug fixes.', 'Conquer the tournament with improved gameplay logic.', 'The first updated revision of Killer Instinct Gold.', 'Killer Instinct Gold (USA) (Rev A) provides minor balance tweaks and performance improvements, ensuring a smoother combat experience for N64 players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killer-instinct-gold-usa-rev-b', 'N64', 'Killer Instinct Gold (USA) (Rev B)', '1996', 'Fighting', 'Rare', '2', 'Arcade Fighting', '2D/3D fighting game with final technical polish.', 'Master the ultimate combo with the most stable US build.', 'The final technical revision of Killer Instinct Gold.', 'Killer Instinct Gold (USA) (Rev B) is the definitive version of the game, fixing rare glitches and optimizing the 64-bit engine for the ultimate fighting session.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-boos-dream-invasion', 'N64', 'King Boo''s Dream Invasion', '2020', 'Platformer', 'Independent', '1', 'Fan Game', '3D platforming in a dark, dream-like mansion.', 'Stop King Boo''s invasion of the dream world.', 'A spooky and creative character-focused mod for SM64.', 'King Boo''s Dream Invasion features eerie atmosphere and unique puzzles. Navigate through the spectral world to stop the ghost king on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-hill-64---extreme-snowboarding-japan', 'N64', 'King Hill 64 - Extreme Snowboarding (Japan)', '1998', 'Sports', 'Konami', '4', 'Snowboarding', 'High-speed extreme snowboarding with tricks.', 'Win the race and perform spectacular stunts in the snow.', 'The Japanese release of the racer Big Mountain 2000.', 'King Hill 64 features realistic physics and diverse mountain tracks. Master the carving and jumping mechanics in this polished Japanese snowboarding sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kiratto-kaiketsu!-64-tanteidan-japan', 'N64', 'Kiratto Kaiketsu! 64 Tanteidan (Japan)', '1999', 'Adventure', 'Konami', '1', 'Mystery', '3D mystery adventure with localized Japanese text.', 'Solve the detective cases with your team of 64-bit sleuths.', 'A unique Japan-exclusive adventure and puzzle game.', 'Kiratto Kaiketsu! 64 Tanteidan follows a group of young detectives. Use your wits to find clues and solve environmental puzzles in this charming N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-64---the-crystal-shards-europe', 'N64', 'Kirby 64 - The Crystal Shards (Europe)', '2001', 'Platformer', 'HAL Laboratory', '1', '3D Platformer', '2.5D side-scrolling platformer with power combos.', 'Combine abilities to defeat Dark Matter and save the stars.', 'The European release of Kirby''s 64-bit adventure.', 'Kirby 64 - The Crystal Shards (Europe) is a visual treat. Experiment with dozens of ability combinations like the Fire-Sword and Explosive-Star on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-64---the-crystal-shards-usa', 'N64', 'Kirby 64 - The Crystal Shards (USA)', '2001', 'Platformer', 'HAL Laboratory', '1', '3D Platformer', '2.5D side-scrolling platformer with power combos.', 'Collect every Crystal Shard to see the secret ending.', 'The North American release of the beloved Kirby title.', 'Kirby 64 - The Crystal Shards (USA) features charming characters and accessible gameplay. It''s a classic platformer that showcases the creative spirit of HAL Laboratory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klonoa', 'N64', 'Klonoa', '1997', 'Platformer', 'Namco', '1', '3D Platformer', '2.5D/3D platforming featuring the Namco mascot.', 'Explore the world of Lunatea as the Dream Traveler.', 'A character-focused mod bringing Klonoa to the N64.', 'Klonoa brings the "door to phantomile" charm to the 64-bit engine. Experience the unique wind-bullet mechanics in this creative and colorful fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knife-edge---nose-gunner-europe', 'N64', 'Knife Edge - Nose Gunner (Europe)', '1998', 'Shooter', 'Kemco', '1', 'Rail Shooter', 'Rail-shooter featuring heavy artillery and nose-gunners.', 'Defeat the alien invaders from the cockpit of your ship.', 'The European version of the high-octane 3D shooter.', 'Knife Edge - Nose Gunner (Europe) features 4-player cooperative action. Coordinate with your team to blast through enemy fleets in this intense N64 arcade port.');
