INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knife-edge---nose-gunner-usa', 'N64', 'Knife Edge - Nose Gunner (USA)', '1998', 'Shooter', 'Kemco', '1', 'Rail Shooter', 'Rail-shooter featuring heavy artillery and nose-gunners.', 'Blast your way through Martian bases and enemy ships.', 'The North American release of the intense rail-shooter.', 'Knife Edge - Nose Gunner (USA) is known for its frantic gameplay and cooperative mode. It’s an arcade-style experience that tests your reflexes and teamwork.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knockout-kings-2000-europe', 'N64', 'Knockout Kings 2000 (Europe)', '1999', 'Sports', 'Electronic Arts', '2', 'Boxing', 'Professional boxing with legendary fighters.', 'Win the heavyweight belt as Muhammad Ali or Sugar Ray.', 'The European release of the polished boxing sim.', 'Knockout Kings 2000 (Europe) features realistic damage and a deep career mode. Master the art of the pugilist with smooth N64 animations and controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knockout-kings-2000-usa', 'N64', 'Knockout Kings 2000 (USA)', '1999', 'Sports', 'Electronic Arts', '2', 'Boxing', 'Professional boxing with legendary fighters.', 'Create your own boxer and rise through the rankings.', 'The North American release of the Knockout Kings debut.', 'Knockout Kings 2000 (USA) brings the excitement of the ring to the N64. With its roster of legends and strategic combat, it’s the premier boxing title on the system.');
