INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kobe-bryant-in-nba-courtside-europe', 'N64', 'Kobe Bryant in NBA Courtside (Europe)', '1998', 'Sports', 'Nintendo', '4', 'Basketball', 'Professional basketball with arcade accessibility.', 'Win the NBA championship as the legendary Kobe Bryant.', 'The European release of the high-speed basketball hit.', 'Kobe Bryant in NBA Courtside features fluid 60 FPS gameplay and a focused career mode. Master the court with Kobe''s signature moves on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kobe-bryants-nba-courtside-usa', 'N64', 'Kobe Bryant''s NBA Courtside (USA)', '1998', 'Sports', 'Nintendo', '4', 'Basketball', 'Professional basketball with realistic animations.', 'Lead your favorite NBA team to the finals in the USA.', 'The North American release of the acclaimed Kobe racer.', 'Kobe Bryant''s NBA Courtside (USA) is known for its impressive graphics and tight controls. It remains one of the most playable basketball sims on the Nintendo 64.');
