INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-zelda-the---master-quest-redux', 'N64', 'Legend of Zelda, The - Master Quest Redux', '2022', 'Action', 'Fan Project', '1', 'ROM Hack', 'Action-adventure with redesigned dungeon puzzles.', 'Experience Ocarina of Time with mirrored and harder dungeons.', 'A high-quality restoration of the Master Quest experience.', 'Legend of Zelda - Master Quest Redux offers a fresh challenge for veterans. Solve redesigned puzzles and encounter tougher enemies in this definitive N64 mod.');
