INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-racers-usa-enfrdeesitnlsvnodafi', 'N64', 'LEGO Racers (USA) (En,Fr,De,Es,It,Nl,Sv,No,Da,Fi)', '1999', 'Racing', 'High Voltage Software', '4', 'Arcade Racing', 'Kart racing with customizable LEGO vehicles.', 'Win the ultimate race and unlock all LEGO pieces.', 'The North American release of the creative kart racer.', 'LEGO Racers (USA) is a family-favorite title. Collect power-ups and use the warp mechanics to outpace your rivals in this colorful 64-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lets-smash-japan', 'N64', 'Let''s Smash (Japan)', '1999', 'Fighting', 'HAL Laboratory', '4', 'Party Fighting', 'Professional tennis simulation with varied courts.', 'Win the grand slam in this Japan-exclusive tennis title.', 'A polished and realistic tennis game for the Japanese market.', 'Let''s Smash features diverse characters and smooth 3D animations. Experience technical tennis gameplay with responsive controls on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lode-runner-3-d-europe-enfrdeesit', 'N64', 'Lode Runner 3-D (Europe) (En,Fr,De,Es,It)', '1999', 'Action', 'Tozai Games', '2', 'Action Puzzle', '3D puzzle-platforming with trap-setting mechanics.', 'Collect the gold and outsmart the guards in 3D levels.', 'The European version of the classic puzzle revival.', 'Lode Runner 3-D (Europe) brings the retro franchise into a full 3D perspective. Solve complex puzzles and navigate through 5 unique worlds on the N64.');
