INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lode-runner-3-d-usa', 'N64', 'Lode Runner 3-D (USA)', '1999', 'Action', 'Tozai Games', '2', 'Action Puzzle', '3D puzzle-platforming with an integrated level editor.', 'Solve over 200 puzzles and design your own stages.', 'The North American release of the 3D puzzle hit.', 'Lode Runner 3-D (USA) is a deep and challenging experience. With its clever level design and custom editor, it offers endless hours of brain-teasing fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-universe-15-kappowsers-legacy', 'N64', 'Lost Universe 1.5 Kappowser''s Legacy', '2020', 'Action', 'Fan Project', '1', 'ROM Hack', 'Surreal 3D platforming with a cosmic horror theme.', 'Survive the "Kappowser" and reclaim the galaxy.', 'A dark and creative mod for the Mario 64 engine.', 'Lost Universe 1.5 Kappowser''s Legacy features custom boss fights and eerie environments. Experience a unique narrative-driven adventure on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('low-poly-promo-models-luigi', 'N64', 'Low Poly Promo Models (Luigi)', '1997', 'Utility', 'Nintendo', '1', 'Promotional', '3D model showcase for technical enthusiasts.', 'View the early low-poly promotional model of Luigi.', 'A technical restoration of pre-release N64 assets.', 'Low Poly Promo Models (Luigi) gives a glimpse into the N64''s development history. Study the original modeling style used for marketing the console.');
