INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lugs-delightful-dioramas', 'N64', 'Lug''s Delightful Dioramas', '2023', 'Puzzle', 'Independent', '1', 'Fan Game', 'Precision platforming in miniature 3D environments.', 'Find the stars hidden within the compact diorama levels.', 'A high-quality "bite-sized" world mod for Mario 64.', 'Lug''s Delightful Dioramas focuses on intricate level design in small spaces. Master the camera and your movement in these beautifully crafted N64 scenes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('luigi-mix-king-with-vacuum-64', 'N64', 'Luigi Mix King With Vacuum 64', '2022', 'Action', 'Fan Project', '1', 'Fan Game', '3D platforming crossover with vacuum mechanics.', 'Clean up the castle and defeat bosses as King Luigi.', 'A creative mod inspired by Luigi''s Mansion.', 'Luigi Mix King With Vacuum 64 gives Luigi his iconic Poltergust vacuum. Sull ghosts and solve environmental puzzles in this unique N64 crossover.');
