INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lylat-wars-australia-enfrde', 'N64', 'Lylat Wars (Australia) (En,Fr,De)', '1997', 'Shooter', 'Nintendo', '1', 'Rail Shooter', 'On-rails sci-fi shooter with cinematic presentation.', 'Save the Lylat System from the evil scientist Andross.', 'The Australian release of the game known as Star Fox 64.', 'Lylat Wars (Australia) features the iconic Rumble Pak support and full voice acting. Fly the Arwing through epic planetary battles on the N64.');
