INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-football-64-europe', 'N64', 'Madden Football 64 (Europe)', '1997', 'Sports', 'Electronic Arts', '4', 'American Football', 'Professional American football with 1997 licensing.', 'Win the Super Bowl in the first 3D Madden on N64.', 'The European debut of the legendary football series.', 'Madden Football 64 (Europe) features the "Madden" name and strategic depth. Experience the early days of 64-bit football with real teams and tactics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-football-64-usa', 'N64', 'Madden Football 64 (USA)', '1997', 'Sports', 'Electronic Arts', '4', 'American Football', 'Professional American football with strategic playbooks.', 'Master the gridiron in the first 64-bit Madden entry.', 'The original North American release of the 1997 season.', 'Madden Football 64 (USA) revolutionized the genre with its 3D player models and complex playbooks. It’s the origin of the modern football sim era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-2000-usa', 'N64', 'Madden NFL 2000 (USA)', '1999', 'Sports', 'Electronic Arts', '4', 'American Football', 'Professional American football with the 1999 season.', 'Lead your franchise to glory with updated graphics.', 'The first Madden to feature the "NFL" license in the title.', 'Madden NFL 2000 (USA) offers a faster pace and more detailed stadiums. Experience the millennium edition of the world''s premier football game on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-2001-usa', 'N64', 'Madden NFL 2001 (USA)', '2000', 'Sports', 'Electronic Arts', '4', 'American Football', 'Professional American football with refined AI.', 'Win the championship in the definitive 2001 edition.', 'The North American release of the polished NFL sim.', 'Madden NFL 2001 (USA) features smoother animations and expanded management modes. It’s a high-water mark for the series'' technical performance on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-2002-usa', 'N64', 'Madden NFL 2002 (USA)', '2001', 'Sports', 'Electronic Arts', '4', 'American Football', 'Professional American football with the final N64 roster.', 'Conquer the league in the final Madden title for the console.', 'The final North American release of the Madden series on N64.', 'Madden NFL 2002 (USA) represents the peak of N64 football technology. With the most complete rosters and refined gameplay, it''s the ultimate simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-99-europe', 'N64', 'Madden NFL 99 (Europe)', '1998', 'Sports', 'Electronic Arts', '4', 'American Football', 'Professional American football with 1998 rosters.', 'Build your dynasty in the 1998 season for Europe.', 'The European release of the massive NFL 99 update.', 'Madden NFL 99 (Europe) features incredible depth and the iconic "one-button" mode for beginners. Experience the strategy of the NFL with polished 64-bit visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('madden-nfl-99-usa', 'N64', 'Madden NFL 99 (USA)', '1998', 'Sports', 'Electronic Arts', '4', 'American Football', 'Professional American football with 1998 rosters.', 'Master the play-by-play with the legendary John Madden.', 'The North American release of the 1998 football hit.', 'Madden NFL 99 (USA) introduced a new physics engine and deeper franchise management. It remains a fan-favorite for its balance and classic 90s presentation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-tetris-challenge-europe', 'N64', 'Magical Tetris Challenge (Europe)', '1998', 'Puzzle', 'Capcom', '2', 'Tetris', 'Competitive puzzle-matching with Disney flair.', 'Outsmart Pete and the Big Bad Wolf in Tetris battles.', 'The European version of the Capcom-Disney puzzle hit.', 'Magical Tetris Challenge (Europe) brings the precision of Tetris to the world of Mickey Mouse. Master the "magical" blocks and special attacks in this vibrant N64 puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-tetris-challenge-germany', 'N64', 'Magical Tetris Challenge (Germany)', '1998', 'Puzzle', 'Capcom', '2', 'Tetris', 'Competitive puzzle-matching with localized text.', 'Solve magical puzzles in this German localized edition.', 'The localized German version of the magical puzzle game.', 'Magical Tetris Challenge (Germany) features the full Disney campaign with German menus. Enjoy polished 64-bit animations and addictive head-to-head puzzle action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-tetris-challenge-usa', 'N64', 'Magical Tetris Challenge (USA)', '1998', 'Puzzle', 'Capcom', '2', 'Tetris', 'Competitive puzzle-matching with a story mode.', 'Complete the quest as Mickey, Minnie, Donald, or Goofy.', 'The North American release of the acclaimed Capcom puzzler.', 'Magical Tetris Challenge (USA) is a colorful and strategic take on the classic Tetris formula. Perfect for both casual players and hardcore puzzle enthusiasts on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-tetris-challenge-featuring-mickey-japan', 'N64', 'Magical Tetris Challenge featuring Mickey (Japan)', '1999', 'Puzzle', 'Capcom', '2', 'Tetris', 'Competitive puzzle-matching with Japanese text.', 'Defeat your rivals in this original Japanese release.', 'The Japanese version of the Disney-themed Tetris title.', 'Magical Tetris Challenge (Japan) features the iconic Disney cast and high-quality 2D/3D hybrid visuals. Experience the origin of this unique Capcom collaboration on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-64-japan', 'N64', 'Mahjong 64 (Japan)', '1997', 'Tabletop', 'Nintendo', '4', 'Mahjong', 'Realistic 3D Mahjong simulation.', 'Win the professional tournament and master the tiles.', 'A specialized Japan-exclusive Mahjong title.', 'Mahjong 64 (Japan) offers a clean and accessible interface for the traditional tile game. Test your strategy against skilled AI opponents in this classic N64 sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-hourouki-classic-japan', 'N64', 'Mahjong Hourouki Classic (Japan)', '1997', 'Tabletop', 'Nintendo', '4', 'Mahjong', 'Classic-style Mahjong with a historical theme.', 'Rise through the ranks of the Mahjong underworld.', 'A Japan-exclusive Mahjong game with a retro aesthetic.', 'Mahjong Hourouki Classic brings the traditional atmosphere of Mahjong parlors to the N64. Experience deep tactical gameplay with a focus on realism.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mahjong-master-japan', 'N64', 'Mahjong Master (Japan)', '1997', 'Tabletop', 'Nintendo', '4', 'Mahjong', 'Competitive Mahjong with varied difficulty levels.', 'Prove your skills and become a true Mahjong Master.', 'A polished Japan-exclusive title for Mahjong veterans.', 'Mahjong Master features advanced AI and multiple tournament modes. It is a comprehensive package for fans of the ancient game on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('major-league-baseball-featuring-ken-griffey-jr-australia', 'N64', 'Major League Baseball featuring Ken Griffey Jr. (Australia)', '1998', 'Sports', 'Angel Studios', '4', 'Baseball', 'Arcade-style baseball with official MLB licensing.', 'Lead your team to the World Series victory in Australia.', 'The Australian release of the Ken Griffey Jr. baseball hit.', 'Major League Baseball featuring Ken Griffey Jr. (Australia) features realistic player stats and accessible home-run mechanics. Experience the American pastime on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('major-league-baseball-featuring-ken-griffey-jr-usa', 'N64', 'Major League Baseball featuring Ken Griffey Jr. (USA)', '1998', 'Sports', 'Angel Studios', '4', 'Baseball', 'Arcade-style baseball with official MLB licensing.', 'Master the "super pitch" and knock it out of the park.', 'The definitive North American release of the MLB classic.', 'Major League Baseball featuring Ken Griffey Jr. (USA) is famous for its fast pace and vibrant graphics. It remains a legendary sports title in the Nintendo 64 library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('majoras-mask-redux-v20', 'N64', 'Majora''s Mask Redux v2.0', '2023', 'Action', 'Fan Project', '1', 'ROM Hack', 'Action-adventure with massive quality-of-life updates.', 'Save Termina with better controls and an improved menu.', 'A definitive "modernized" overhaul of Majora''s Mask.', 'Majora''s Mask Redux v2.0 fixes the original game''s frustrations. Enjoy faster text, d-pad item mapping, and refined logic in this ultimate Zelda N64 mod.');
