INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mario-&-flybro:-the-mysterious-mansion', 'N64', 'Mario & Flybro: The Mysterious Mansion', '2022', 'Adventure', 'Fan Project', '1', 'Fan Game', '3D platforming with a cooperative "tag" mechanic.', 'Solve the mysteries of the mansion as Mario and Flybro.', 'A creative mod featuring a unique custom companion.', 'Mario & Flybro features dual-character puzzles and custom level design. Explore the haunted mansion in this innovative and charming N64 adventure.');
